const body = {
  model: 'deepseek/deepseek-v4.1-flash',
  temperature: 0,
  max_tokens: 80,
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'pre02a_smoke',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          status: { type: 'string', enum: ['ok'] },
          message: { type: 'string' }
        },
        required: ['status', 'message']
      }
    }
  },
  messages: [
    {
      role: 'system',
      content: 'Это техническая проверка API. Верни только данные по заданной JSON Schema.'
    },
    {
      role: 'user',
      content: 'Проверка PRE-02A из self-hosted n8n. Верни status=ok и короткое сообщение на русском.'
    }
  ]
};
return [{json:{zapros_modeli:body}}];

const x = $json || {};
const model = String(x.model || '');
const content = x.choices?.[0]?.message?.content;
let parsed = null;
try {
  parsed = typeof content === 'object' && content ? content : JSON.parse(String(content || ''));
} catch {}
const ok = Boolean(
  model.includes('deepseek') &&
  parsed &&
  parsed.status === 'ok' &&
  typeof parsed.message === 'string' &&
  parsed.message.length > 0
);
if (!ok) {
  throw new Error('PRE-02A: OpenRouter ответил, но структура/модель не прошла проверку');
}
return [{
  json: {
    pre02a_status: 'verified',
    requested_model: 'deepseek/deepseek-v4.1-flash',
    returned_model: model,
    structured_output_ok: true,
    message: parsed.message,
    usage: x.usage || null
  }
}];
